1	package com.example.starter.firmware.service;
2	
3	import com.example.starter.firmware.api.PullResponse;
4	import com.example.starter.firmware.api.ReceiptRequest;
5	import com.example.starter.firmware.api.TaskListResponse;
6	import com.example.starter.firmware.api.TaskView;
7	import com.example.starter.firmware.domain.Device;
8	import com.example.starter.firmware.domain.ReceiptResult;
9	import com.example.starter.firmware.domain.ReleaseOrder;
10	import com.example.starter.firmware.domain.ReleaseStatus;
11	import com.example.starter.firmware.domain.RolloutTask;
12	import com.example.starter.firmware.domain.TaskStatus;
13	import com.example.starter.firmware.error.ApiException;
14	import com.example.starter.firmware.repo.DeviceRepository;
15	import com.example.starter.firmware.repo.PauseRecordRepository;
16	import com.example.starter.firmware.repo.ReleaseRepository;
17	import com.example.starter.firmware.repo.TaskRepository;
18	import org.springframework.dao.DuplicateKeyException;
19	import org.springframework.stereotype.Service;
20	
21	import java.time.Clock;
22	import java.time.Instant;
23	import java.util.List;
24	
25	/**
26	 * 投放任务：设备拉取与回执。与取消、恢复并发时统一先锁发布单行，再操作任务，形成一致提交顺序。
27	 * 回执首次终结任务时在发布单行锁内累计当前监控轮次统计，达到阈值即在同一事务原子暂停。
28	 */
29	@Service
30	public class TaskService {
31	
32	    private final TaskRepository taskRepository;
33	    private final ReleaseRepository releaseRepository;
34	    private final DeviceRepository deviceRepository;
35	    private final PauseRecordRepository pauseRecordRepository;
36	    private final DeviceService deviceService;
37	    private final ReleaseService releaseService;
38	    private final IdempotencyService idempotency;
39	    private final Clock clock;
40	
41	    public TaskService(TaskRepository taskRepository, ReleaseRepository releaseRepository,
42	                       DeviceRepository deviceRepository, PauseRecordRepository pauseRecordRepository,
43	                       DeviceService deviceService, ReleaseService releaseService,
44	                       IdempotencyService idempotency, Clock clock) {
45	        this.taskRepository = taskRepository;
46	        this.releaseRepository = releaseRepository;
47	        this.deviceRepository = deviceRepository;
48	        this.pauseRecordRepository = pauseRecordRepository;
49	        this.deviceService = deviceService;
50	        this.releaseService = releaseService;
51	        this.idempotency = idempotency;
52	        this.clock = clock;
53	    }
54	
55	    /**
56	     * 设备拉取：已存在任务直接返回；否则仅当型号与当前版本匹配、分桶号小于比例且发布单 ACTIVE 时创建。
57	     * PAUSED 时不创建新任务，已有任务仍可查看与回执。
58	     */
59	    public PullResponse pull(String deviceId, String requestId) {
60	        String fingerprint = String.join("|", "task.pull", deviceId);
61	        return idempotency.execute(requestId, "task.pull", fingerprint, () -> {
62	            Device device = deviceService.findDevice(deviceId);
63	            var activeOrder = releaseRepository.findActiveByModel(device.model());
64	            if (activeOrder.isEmpty()) {
65	                return new PullResponse(null);
66	            }
67	            ReleaseOrder order = releaseRepository.findByIdForUpdate(activeOrder.get().id())
68	                    .orElseThrow(() -> ApiException.notFound("RELEASE_NOT_FOUND", "发布单不存在"));
69	            var existing = taskRepository.findByReleaseAndDevice(order.id(), deviceId);
70	            if (existing.isPresent()) {
71	                return new PullResponse(TaskView.of(existing.get(), order));
72	            }
73	            if (order.status() != ReleaseStatus.ACTIVE
74	                    || !device.currentVersion().equals(order.fromVersion())
75	                    || device.bucketNo() >= order.ratio()) {
76	                return new PullResponse(null);
77	            }
78	            long taskId;
79	            try {
80	                taskId = taskRepository.insert(order.id(), deviceId);
81	            } catch (DuplicateKeyException e) {
82	                RolloutTask task = taskRepository.findByReleaseAndDevice(order.id(), deviceId)
83	                        .orElseThrow(() -> new IllegalStateException("任务唯一约束冲突后未找到任务"));
84	                return new PullResponse(TaskView.of(task, order));
85	            }
86	            RolloutTask task = taskRepository.findById(taskId)
87	                    .orElseThrow(() -> new IllegalStateException("任务创建后读取失败"));
88	            return new PullResponse(TaskView.of(task, order));
89	        }, PullResponse.class);
90	    }
91	
92	    /**
93	     * 回执：首次回执终结任务并计入完成时所在监控轮次，仅 SUCCESS 更新设备当前版本；
94	     * 同结果重复成功（不重复计数），改结果 409；已取消任务的后到回执 409 且不更新设备版本。
95	     * 样本达到下限且失败率越限时，同事务将仍为 ACTIVE 的发布单原子转为 PAUSED 并落暂停记录。
96	     */
97	    public TaskView receipt(long taskId, ReceiptRequest request) {
98	        String fingerprint = String.join("|", "task.receipt", String.valueOf(taskId), request.result().name());
99	        return idempotency.execute(request.requestId(), "task.receipt", fingerprint, () -> {
100	            RolloutTask snapshot = taskRepository.findById(taskId)
101	                    .orElseThrow(() -> ApiException.notFound("TASK_NOT_FOUND", "任务不存在: " + taskId));
